#[cfg(test)]
pub(crate) struct ProjectionCaseAliasGuard;

#[cfg(test)]
impl Drop for ProjectionCaseAliasGuard {
    fn drop(&mut self) {
        PROJECTION_CASE_ALIAS.with(|alias| {
            alias.borrow_mut().take();
        });
    }
}

/// Model a case-insensitive exact-path lookup without changing production path
/// resolution. While `existing` is present, resolving `requested` addresses
/// that exact physical spelling; after retirement, a create uses `requested`.
#[cfg(test)]
pub(crate) fn projection_case_alias_for_test(
    requested: &str,
    existing: &str,
) -> ProjectionCaseAliasGuard {
    PROJECTION_CASE_ALIAS.with(|alias| {
        let mut alias = alias.borrow_mut();
        assert!(
            alias.is_none(),
            "projection case-alias hook is already armed"
        );
        *alias = Some((requested.to_owned(), existing.to_owned()));
    });
    ProjectionCaseAliasGuard
}

#[cfg(test)]
fn projection_case_alias_physical_path(root: &Path, requested: &str) -> Option<String> {
    PROJECTION_CASE_ALIAS.with(|alias| {
        let alias = alias.borrow();
        let (hook_requested, existing) = alias.as_ref()?;
        (hook_requested == requested && fs::symlink_metadata(root.join(existing)).is_ok())
            .then(|| existing.clone())
    })
}

#[cfg(test)]
fn projection_case_alias_is_armed(requested: &str) -> bool {
    PROJECTION_CASE_ALIAS.with(|alias| {
        alias
            .borrow()
            .as_ref()
            .is_some_and(|(hook_requested, _)| hook_requested == requested)
    })
}

#[cfg(test)]
struct ManagedMigrationWriterObserver {
    observation: Rc<Cell<ManagedMigrationWriterBoundary>>,
}

#[cfg(test)]
impl ManagedMigrationWriterObserver {
    fn new() -> Self {
        let observation = Rc::new(Cell::new(ManagedMigrationWriterBoundary::default()));
        MANAGED_MIGRATION_WRITER_OBSERVER.with(|observer| {
            let mut observer = observer.borrow_mut();
            assert!(
                observer.is_none(),
                "managed migration writer observer is already installed"
            );
            *observer = Some(Rc::clone(&observation));
        });
        Self { observation }
    }

    fn observation(&self) -> ManagedMigrationWriterBoundary {
        self.observation.get()
    }
}

#[cfg(test)]
impl Drop for ManagedMigrationWriterObserver {
    fn drop(&mut self) {
        MANAGED_MIGRATION_WRITER_OBSERVER.with(|observer| {
            let mut observer = observer.borrow_mut();
            if observer
                .as_ref()
                .is_some_and(|current| Rc::ptr_eq(current, &self.observation))
            {
                observer.take();
            }
        });
    }
}

#[cfg(test)]
fn observe_managed_migration_writer(update: impl FnOnce(&mut ManagedMigrationWriterBoundary)) {
    MANAGED_MIGRATION_WRITER_OBSERVER.with(|observer| {
        let observer = observer.borrow();
        let Some(observation) = observer.as_ref() else {
            return;
        };
        let mut value = observation.get();
        update(&mut value);
        observation.set(value);
    });
}

