#[cfg(any(target_os = "linux", target_os = "android"))]
fn rename_managed_noreplace(
    source_dir: &Dir,
    source: &str,
    destination_dir: &Dir,
    destination: &str,
) -> io::Result<()> {
    use std::ffi::CString;
    use std::os::fd::{AsFd, AsRawFd};

    let source = CString::new(source)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid source name"))?;
    let destination = CString::new(destination)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid destination name"))?;
    let result = unsafe {
        libc::syscall(
            libc::SYS_renameat2,
            source_dir.as_fd().as_raw_fd(),
            source.as_ptr(),
            destination_dir.as_fd().as_raw_fd(),
            destination.as_ptr(),
            libc::RENAME_NOREPLACE as libc::c_uint,
        )
    };
    (result == 0)
        .then_some(())
        .ok_or_else(io::Error::last_os_error)
}

#[cfg(target_os = "macos")]
fn rename_managed_noreplace(
    source_dir: &Dir,
    source: &str,
    destination_dir: &Dir,
    destination: &str,
) -> io::Result<()> {
    use std::ffi::CString;
    use std::os::fd::{AsFd, AsRawFd};

    let source = CString::new(source)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid source name"))?;
    let destination = CString::new(destination)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid destination name"))?;
    let result = unsafe {
        libc::renameatx_np(
            source_dir.as_fd().as_raw_fd(),
            source.as_ptr(),
            destination_dir.as_fd().as_raw_fd(),
            destination.as_ptr(),
            libc::RENAME_EXCL as libc::c_uint,
        )
    };
    (result == 0)
        .then_some(())
        .ok_or_else(io::Error::last_os_error)
}

