    fn jdto(name: &str) -> PageDto {
        PageDto {
            name: name.into(),
            kind: PageKind::Journal,
            title: name.into(),
            pre_block: None,
            blocks: vec![BlockDto {
                id: String::new(),
                raw: "hi".into(),
                collapsed: false,
                children: vec![],
                breadcrumb: vec![],
                ..Default::default()
            }],
            rev: None,
            format: Format::Md,
            read_only: false,
            path: String::new(),
            guide: false,
        }
    }

